#!/usr/bin/env bash\nset -e\n\n# Build the Docker image\ndocker build -t nightly-qr-code-generator-test . > /dev/null\n\n# Create a temporary directory for output\ntmpdir=$(mktemp -d)\ntrap "rm -rf $tmpdir" EXIT\n\n# Run the container with a sample message\ndocker run --rm -v "$tmpdir":/data nightly-qr-code-generator-test "Apocalypse"\n\n# Verify that qr.png exists and is non‑empty\nif [[ -f "$tmpdir/qr.png" && -s "$tmpdir/qr.png" ]]; then\n  echo "Test passed: QR code generated."\n  exit 0\nelse\n  echo "Test failed: QR code not generated."\n  exit 1\nfi\n\n# Mock rationale: The test builds the image locally, runs it with a known input,\n# and checks that the output file exists and has size > 0, ensuring deterministic\n# behavior without external network dependencies.
